<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {ArrowLeft,ArrowRight,ArrowUp,ArrowDown,Coins,Footprints,Pause,Play,Trophy} from 'lucide-vue-next'
import DogSprite from './DogSprite.vue'
import {db,fail,friendly} from '../lib/supabase'
import {user} from '../lib/session'
import {newRunner,stepRunner,runScore,runnerKey,swipeAction,RUN_STEP,type RunAction} from '../lib/runner'
const props=defineProps<{disabled?:boolean;accessory?:string}>(),emit=defineEmits<{updated:[];active:[value:boolean]}>()
const shell=ref<HTMLElement|null>(null),field=ref<HTMLElement|null>(null),mode=ref<'menu'|'ready'|'playing'|'paused'|'result'>('menu')
const state=ref(newRunner(1)),busy=ref(false),error=ref(''),best=ref(0),ranking=ref<{alias:string;score:number}[]>([]),showRanks=ref(false)
const award=ref<{score:number;coins:number;xp:number;best:number;tokens:number}|null>(null)
let run:{id:string;seed:number}|null=null,inputs:number[]=[],queue:RunAction[]=[],lastInput=-10,raf=0,lastTime=0,accumulator=0,owner='',alive=true
let pointer:{id:number;x:number;y:number}|null=null
const score=computed(()=>runScore(state.value)),jumpHeight=computed(()=>Math.sin(state.value.jump/42*Math.PI)*55)
function focus(){field.value?.focus({preventScroll:true})}
async function records(){const id=user.value?.id;const {data,error:e}=await db.rpc('wedding_runner_records');if(!e&&alive&&id===user.value?.id){best.value=data.best;ranking.value=data.ranking}}
async function start(){if(busy.value||props.disabled||!user.value)return;busy.value=true;error.value='';owner=user.value.id
 try{const {data,error:e}=await db.rpc('wedding_runner_start');fail(e);if(!alive||owner!==user.value?.id)return;run=data;state.value=newRunner(data.seed);inputs=[];queue=[];lastInput=-10;award.value=null;mode.value='ready';emit('active',true);emit('updated');await nextTick();shell.value?.scrollIntoView({block:'start',behavior:'instant'});focus()}catch(e){error.value=friendly(e)}finally{busy.value=false}
}
function schedule(){lastTime=performance.now();accumulator=0;raf=requestAnimationFrame(frame)}
function begin(){if(mode.value!=='ready')return;mode.value='playing';focus();schedule()}
function input(action:RunAction){if(!action)return;if(mode.value==='ready')begin();if(mode.value==='playing'&&queue.length<2){queue.push(action);focus()}}
function frame(time:number){if(mode.value!=='playing')return;const delta=time-lastTime;lastTime=time;if(delta>350){pause();return}accumulator+=delta
 while(accumulator>=RUN_STEP&&!state.value.dead){let action:RunAction=0;if(queue.length&&state.value.tick+1-lastInput>=4){action=queue.shift()!;lastInput=state.value.tick+1;inputs.push(lastInput*10+action)}stepRunner(state.value,action);accumulator-=RUN_STEP}
 if(state.value.dead){mode.value='result';void finish();return}raf=requestAnimationFrame(frame)
}
function pause(){if(mode.value!=='playing')return;cancelAnimationFrame(raf);queue=[];pointer=null;mode.value='paused'}
function resume(){mode.value='playing';focus();schedule()}
async function finish(){if(!run||busy.value||award.value)return;busy.value=true;error.value='';try{const {data,error:e}=await db.rpc('wedding_runner_finish',{run_id:run.id,inputs,ticks:state.value.tick});fail(e);if(!alive||owner!==user.value?.id)return;award.value=data;best.value=data.best;emit('updated');void records()}catch(e){if(alive)error.value=friendly(e)}finally{busy.value=false}}
function leave(){cancelAnimationFrame(raf);queue=[];pointer=null;mode.value='menu';run=null;emit('active',false)}
function key(e:KeyboardEvent){if(!['ready','playing','paused'].includes(mode.value)||e.ctrlKey||e.metaKey||e.altKey)return;const target=e.target as HTMLElement|null
 if(target?.isContentEditable||target?.closest('input,textarea,select,[role="dialog"]'))return
 if(target&&target!==document.body&&!shell.value?.contains(target))return
 if(['Escape','KeyP'].includes(e.code)){e.preventDefault();e.stopPropagation();if(!e.repeat){if(mode.value==='playing')pause();else if(mode.value==='paused')resume()}return}
 const action=runnerKey(e.code);if(action&&mode.value!=='paused'){e.preventDefault();e.stopPropagation();if(!e.repeat)input(action)}
}
function down(e:PointerEvent){if(mode.value!=='playing'||!e.isPrimary)return;pointer={id:e.pointerId,x:e.clientX,y:e.clientY};field.value?.setPointerCapture(e.pointerId);focus()}
function up(e:PointerEvent){if(pointer?.id!==e.pointerId)return;const action=swipeAction(e.clientX-pointer.x,e.clientY-pointer.y);pointer=null;if(field.value?.hasPointerCapture(e.pointerId))field.value.releasePointerCapture(e.pointerId);input(action)}
function hidden(){if(document.hidden)pause()}
function position(progress:number,lane:number){const depth=progress/10000;return {left:50+(lane-1)*31*(.18+depth*.82)+'%',top:17+depth*64+'%',transform:`translate(-50%,-100%) scale(${.25+depth*.95})`,zIndex:2+Math.floor(depth*20)}}
watch(()=>user.value?.id,()=>{leave();award.value=null;best.value=0;ranking.value=[]})
onMounted(()=>{void records();window.addEventListener('keydown',key,true);document.addEventListener('visibilitychange',hidden)})
onUnmounted(()=>{alive=false;cancelAnimationFrame(raf);window.removeEventListener('keydown',key,true);document.removeEventListener('visibilitychange',hidden);emit('active',false)})
</script>
<template><section ref="shell" class="flappy-game runner-game" :class="{'runner-active':mode!=='menu'}"><template v-if="mode==='menu'"><button class="flappy-card runner-card" :disabled="disabled||busy" @click="start"><div class="flight-cover runner-cover"><span></span><DogSprite mood="playing"/></div><span><b>Huellas Surfer</b><small>Tres carriles. ¡Una aventura a toda pata!</small><em>{{busy?'Preparando…':'¡Vamos a correr! →'}}</em></span></button><div class="flight-record"><Trophy :size="16"/> Tu récord: {{best}} puntos <button @click="showRanks=!showRanks">Clasificación Surfer</button></div><p class="arcade-note">Esquiva, salta y deslízate. Recoge monedas para el armario.<br/>PC: flechas o WASD · Espacio: salto. Móvil: desliza o usa los botones.<br/>3 energía + 2 comida por partida · Hasta 60 s · Premios máximos: 60 monedas y 90 XP.</p><div v-if="showRanks" class="flappy-ranking"><p v-if="!ranking.length">Sé el primero. Activa la clasificación con alias desde tu perfil para aparecer.</p><ol v-else><li v-for="(r,i) in ranking" :key="i">{{r.alias}} <b>{{r.score}} puntos</b></li></ol></div><p v-if="error" class="pet-error" role="alert">{{error}}</p></template><template v-else><header class="flight-toolbar"><button v-if="mode==='result'" :disabled="busy" @click="leave" aria-label="Volver al patio desde Surfer"><ArrowLeft :size="20"/></button><Footprints v-else :size="21"/><b>Huellas Surfer</b><span>{{Math.floor(state.tick/60)}} / 60 s</span><button v-if="mode==='playing'" @click="pause" aria-label="Pausar Surfer"><Pause :size="20"/></button></header><div ref="field" class="flight-field runner-field" tabindex="0" role="application" aria-label="Huellas Surfer: izquierda y derecha para cambiar de carril, espacio o arriba para saltar, abajo para deslizarse." @pointerdown.prevent="down" @pointerup.prevent="up" @pointercancel="pointer=null"><div class="runner-sun"></div><div class="runner-village"><i v-for="n in 6" :key="n"></i></div><div class="runner-grass"></div><div class="runner-road"></div><div class="runner-line left"></div><div class="runner-line right"></div><div class="runner-bunting">▾ ▾ ▾ ▾ ▾ ▾ ▾ ▾</div><div class="runner-hud"><span><b>{{score}}</b> puntos</span><span><Coins :size="16"/> {{state.tokens}}</span></div><template v-for="row in state.rows" :key="row.id"><div class="run-object" :class="['obstacle-'+row.kind]" :style="position(row.progress,row.lane)"><template v-if="row.kind===1"><span>↑</span><i></i><i></i></template><template v-else-if="row.kind===2"><span>↓</span><i></i><i></i></template><template v-else><span>❀</span><i></i></template></div><div class="run-object runner-token" :style="position(row.progress,row.coinLane)">●</div></template><div class="runner-dog" :class="{running:mode==='playing',ducking:state.duck>0}" :style="{left:19+state.lane*31+'%',bottom:`calc(17% + ${jumpHeight}px)`}"><DogSprite :mood="state.jump?'playing':''" :accessory="accessory"/><span v-if="state.duck" class="runner-action-label">¡Abajo!</span></div><div v-if="mode==='ready'" class="flight-overlay" @pointerdown.stop @pointerup.stop><div><Footprints :size="32"/><h4>¡A toda pata!</h4><p>Vallas <b>↑ salta</b> · Arcos <b>↓ deslízate</b><br/>Setos: cambia de carril.</p><small class="runner-intro-controls">PC: ← → / A D · Espacio / ↑ salta · ↓ se agacha.<br/>Móvil: desliza o usa los botones.</small><button @click="begin">¡A correr!</button><button class="flight-secondary" @click="leave">Volver al patio</button></div></div><div v-else-if="mode==='paused'" class="flight-overlay" @pointerdown.stop @pointerup.stop><div><Pause :size="30"/><h4>Un respiro</h4><p>La carrera está en pausa.</p><button @click="resume"><Play :size="16"/> Seguir corriendo</button><button class="flight-secondary" @click="leave">Salir sin recompensa</button></div></div><div v-else-if="mode==='result'" class="flight-overlay" @pointerdown.stop @pointerup.stop><div><Trophy :size="30"/><h4>{{state.tick===3600?'¡Meta conseguida!':'¡Menuda carrera!'}}</h4><p class="result-score">{{score}} <small>puntos · {{state.tokens}} {{state.tokens===1?'moneda recogida':'monedas recogidas'}}</small></p><p v-if="busy" role="status">Guardando tu carrera…</p><div v-else-if="award" class="flight-prizes"><span><Coins :size="16"/> +{{award.coins}}</span><span>✦ +{{award.xp}} XP</span></div><p v-if="award">Tu récord: {{best}} puntos</p><p v-if="error" class="flight-error" role="alert">{{error}}</p><button v-if="error&&!award" :disabled="busy" @click="finish">Reintentar guardar</button><button v-else :disabled="busy||disabled" @click="start">Otra carrera</button><button :disabled="busy" class="flight-secondary" @click="leave">Volver al patio</button></div></div></div><div class="runner-buttons" aria-label="Controles de Huellas Surfer"><button :disabled="mode!=='playing'" @click="input(1)" aria-label="Carril izquierdo"><ArrowLeft :size="20"/><span>Izquierda</span></button><button :disabled="mode!=='playing'" @click="input(3)" aria-label="Saltar"><ArrowUp :size="20"/><span>Saltar</span></button><button :disabled="mode!=='playing'" @click="input(4)" aria-label="Deslizarse"><ArrowDown :size="20"/><span>Deslizar</span></button><button :disabled="mode!=='playing'" @click="input(2)" aria-label="Carril derecho"><ArrowRight :size="20"/><span>Derecha</span></button></div><div class="game-controls-guide"><span><b>PC</b> <kbd>←</kbd> <kbd>→</kbd> carril · <kbd>Espacio</kbd> / <kbd>↑</kbd> salto · <kbd>↓</kbd> deslizar</span><span><kbd>P</kbd> / <kbd>Esc</kbd> pausa · También WASD.</span><span><b>Móvil</b> Desliza en las cuatro direcciones o usa los botones.</span></div></template></section></template>
